final class TaskCatalog
{
	private static final Map<String, String> TASK_NAMES = Map.ofEntries(
		Map.entry("aberrant-spectre", "Aberrant Spectres"),
		Map.entry("abyssal-demon", "Abyssal Demons"),
		Map.entry("aquanite", "Aquanites"),
		Map.entry("araxyte", "Araxytes"),
		Map.entry("banshee", "Banshees"),
		Map.entry("basilisks", "Basilisks"),
		Map.entry("bloodveld", "Bloodveld"),
		Map.entry("cave-crawler", "Cave Crawlers"),
		Map.entry("cave-horror", "Cave Horrors"),
		Map.entry("cockatrice", "Cockatrice"),
		Map.entry("crawling-hand", "Crawling Hands"),
		Map.entry("custodian-stalker", "Custodian Stalkers"),
		Map.entry("dark-beast", "Dark Beasts"),
		Map.entry("drake", "Drakes"),
		Map.entry("dust-devil", "Dust Devils"),
		Map.entry("gargoyle", "Gargoyles"),
		Map.entry("gryphons", "Gryphons"),
		Map.entry("hydra", "Hydras"),
		Map.entry("infernal-mage", "Infernal Mages"),
		Map.entry("jelly", "Jellies"),
		Map.entry("kurask", "Kurask"),
		Map.entry("nechryael", "Nechryael"),
		Map.entry("pyrefiend", "Pyrefiends"),
		Map.entry("rockslug", "Rockslugs"),
		Map.entry("smoke-devil", "Smoke Devils"),
		Map.entry("turoth", "Turoth"),
		Map.entry("venator", "Venators"),
		Map.entry("warped-creatures", "Warped Creatures"),
		Map.entry("wyrm", "Wyrms")
	);
	private static final Set<String> MODIFIERS = Set.of("quantity", "points", "clue", "xp", "unique");
	private static final Map<String, String> IDS_BY_NAME = new HashMap<>();

	static
	{
		TASK_NAMES.forEach((id, name) -> IDS_BY_NAME.put(name.toLowerCase(Locale.ROOT), id));
	}

	private TaskCatalog()
	{
	}

	static String taskIdForName(String name)
	{
		return name == null ? null : IDS_BY_NAME.get(name.trim().toLowerCase(Locale.ROOT));
	}

	static boolean isValidKey(String key)
	{
		if (key == null)
		{
			return false;
		}
		int separator = key.indexOf('/');
		return separator > 0
			&& TASK_NAMES.containsKey(key.substring(0, separator))
			&& MODIFIERS.contains(key.substring(separator + 1));
	}

	static int getMaxRankingSize()
	{
		return TASK_NAMES.size() * MODIFIERS.size();
	}
}

package com.efficientmortimer;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Efficient Mortimer",
	description = "Highlights efficient task choices for post-99 Slayer",
	tags = {"slayer", "mortimer", "ehp"}
)
public class EfficientMortimerPlugin extends Plugin
{
	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private ConfigManager configManager;
	@Inject
	private EfficientMortimerConfig config;
	@Inject
	private Gson gson;
	@Inject
	private MortimerOffers offers;
	@Inject
	private EfficientMortimerOverlay overlay;
	@Inject
	private OverlayManager overlayManager;

	private volatile boolean running;
	private volatile long profileId;
	private boolean refreshNeeded;
	private TaskRanking mainRanking;
	private TaskRanking ironmanRanking;
	private TaskRanking ironmanBarrageRanking;
	private TaskRanking customRanking;
	private volatile DisplayState displayState;

	@Override
	protected void startUp()
	{
		mainRanking = loadBundledRanking("main.json");
		ironmanRanking = loadBundledRanking("ironman.json");
		ironmanBarrageRanking = loadBundledRanking("ironman-barrage.json");
		running = true;
		profileId = configManager.getProfile().getId();
		overlayManager.add(overlay);
		clientThread.invoke(() ->
		{
			if (running)
			{
				reloadCustomList();
				refreshNeeded = true;
			}
		});
	}

	@Override
	protected void shutDown()
	{
		running = false;
		overlayManager.remove(overlay);
		displayState = null;
		mainRanking = null;
		ironmanRanking = null;
		ironmanBarrageRanking = null;
		customRanking = null;
		refreshNeeded = false;
	}

	@Provides
	EfficientMortimerConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(EfficientMortimerConfig.class);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!EfficientMortimerConfig.GROUP.equals(event.getGroup())
			|| configManager.getProfile().getId() != profileId)
		{
			return;
		}
		if ("customList".equals(event.getKey()) || "listMode".equals(event.getKey()))
		{
			long changedProfile = profileId;
			boolean imported = "customList".equals(event.getKey());
			clientThread.invoke(() ->
			{
				if (running && configManager.getProfile().getId() == changedProfile)
				{
					if (imported)
					{
						reloadCustomList();
					}
					refreshNeeded = true;
				}
			});
		}
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		displayState = null;
		clientThread.invoke(() ->
		{
			if (running)
			{
				reloadCustomList();
				profileId = configManager.getProfile().getId();
				refreshNeeded = true;
			}
		});
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.SLAYER_TASK_CHOICE)
		{
			refreshNeeded = true;
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.SLAYER_TASK_CHOICE)
		{
			displayState = null;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (displayState != null)
		{
			refreshNeeded = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		refreshNeeded = true;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		displayState = null;
		refreshNeeded = event.getGameState() == GameState.LOGGED_IN;
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (running && refreshNeeded)
		{
			refreshNeeded = false;
			refreshRecommendation();
		}
	}

	DisplayState getDisplayState()
	{
		return displayState;
	}

	private TaskRanking loadBundledRanking(String filename)
	{
		try (InputStream input = getClass().getResourceAsStream("/com/efficientmortimer/" + filename))
		{
			if (input == null)
			{
				throw new IllegalStateException("Missing bundled task list: " + filename);
			}
			return TaskRanking.parse(gson, new String(input.readAllBytes(), StandardCharsets.UTF_8));
		}
		catch (IOException e)
		{
			throw new IllegalStateException("Could not read bundled task list: " + filename, e);
		}
	}

	private void reloadCustomList()
	{
		try
		{
			customRanking = TaskRanking.parse(gson, config.customList().trim());
		}
		catch (IllegalArgumentException e)
		{
			customRanking = null;
		}
	}

	private void refreshRecommendation()
	{
		if (client.getGameState() != GameState.LOGGED_IN || configManager.getProfile().getId() != profileId)
		{
			displayState = null;
			return;
		}
		MortimerOffers.Snapshot snapshot = offers.read();
		if (snapshot == null)
		{
			displayState = null;
			return;
		}
		if (!snapshot.isComplete())
		{
			displayState = new DisplayState(snapshot, null, snapshot.getMessage());
			return;
		}

		ListMode mode = config.listMode();
		TaskRanking ranking;
		switch (mode)
		{
			case MAIN:
				ranking = mainRanking;
				break;
			case IRONMAN:
				ranking = ironmanRanking;
				break;
			case IRONMAN_BARRAGE:
				ranking = ironmanBarrageRanking;
				break;
			default:
				ranking = customRanking;
		}
		if (ranking == null)
		{
			displayState = null;
			return;
		}
		Recommendation recommendation = ranking.recommend(snapshot.getKeys(), client.getVarbitValue(VarbitID.SLAYER_POINTS));
		String message = null;
		if (recommendation.getAction() == Recommendation.Action.UNAVAILABLE)
		{
			message = mode == ListMode.CUSTOM ? "An offer is missing from this list. Import an updated ranking."
				: "An offer is missing from the " + Text.titleCase(mode) + " list.";
		}
		displayState = new DisplayState(snapshot, recommendation, message);
	}

	static final class DisplayState
	{
		final MortimerOffers.Snapshot snapshot;
		final Recommendation recommendation;
		final String message;

		DisplayState(MortimerOffers.Snapshot snapshot, Recommendation recommendation, String message)
		{
			this.snapshot = snapshot;
			this.recommendation = recommendation;
			this.message = message;
		}
	}
}

package com.efficientmortimer;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import java.io.IOException;
import java.io.StringReader;
import java.math.BigDecimal;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

final class TaskRanking
{
	static final int SKIP_COST = 100;
	private static final int MAX_IMPORT_LENGTH = 16_384;
	private final Map<String, Integer> ranks;
	private final int acceptedCount;

	private TaskRanking(Map<String, Integer> ranks, int acceptedCount)
	{
		this.ranks = Map.copyOf(ranks);
		this.acceptedCount = acceptedCount;
	}

	static TaskRanking parse(Gson gson, String input)
	{
		if (input == null || input.isBlank())
		{
			throw new IllegalArgumentException("Paste a ranking copied from ehp.gg.");
		}
		if (input.length() > MAX_IMPORT_LENGTH)
		{
			throw new IllegalArgumentException("Ranking is too long.");
		}

		JsonObject data;
		try (JsonReader reader = new JsonReader(new StringReader(input)))
		{
			data = gson.getAdapter(JsonObject.class).read(reader);
			if (data == null || reader.peek() != JsonToken.END_DOCUMENT)
			{
				throw new IllegalArgumentException("Paste a valid ranking export.");
			}
		}
		catch (IOException | JsonParseException | IllegalStateException e)
		{
			throw new IllegalArgumentException("Paste a valid ranking export.");
		}

		if (!"efficient-mortimer".equals(stringValue(data.get("type"))))
		{
			throw new IllegalArgumentException("This is not an Efficient Mortimer export.");
		}
		if (integerValue(data.get("version"), "Version") != 1)
		{
			throw new IllegalArgumentException("Unsupported export version. Update Efficient Mortimer.");
		}
		int acceptedCount = integerValue(data.get("acceptedCount"), "Accepted count");
		JsonElement ranking = data.get("ranking");
		if (ranking == null || !ranking.isJsonArray())
		{
			throw new IllegalArgumentException("Export is missing its task ranking.");
		}
		JsonArray entries = ranking.getAsJsonArray();
		if (entries.size() == 0 || entries.size() > TaskCatalog.getMaxRankingSize())
		{
			throw new IllegalArgumentException("Ranking must contain 1 to " + TaskCatalog.getMaxRankingSize() + " entries.");
		}
		if (acceptedCount < 0 || acceptedCount > entries.size())
		{
			throw new IllegalArgumentException("Accepted count is outside the ranking.");
		}

		Map<String, Integer> ranks = new HashMap<>();
		for (int i = 0; i < entries.size(); i++)
		{
			String key = stringValue(entries.get(i));
			if (!TaskCatalog.isValidKey(key))
			{
				throw new IllegalArgumentException("Unknown task or modifier at entry " + (i + 1) + ".");
			}
			if (ranks.putIfAbsent(key, i) != null)
			{
				throw new IllegalArgumentException("Duplicate task and modifier at entry " + (i + 1) + ".");
			}
		}
		return new TaskRanking(ranks, acceptedCount);
	}

	int getSize()
	{
		return ranks.size();
	}

	int getAcceptedCount()
	{
		return acceptedCount;
	}

	Recommendation recommend(List<String> offerKeys, int points)
	{
		if (offerKeys == null || offerKeys.size() < 2 || offerKeys.size() > 3)
		{
			return Recommendation.unavailable();
		}
		int bestSlot = -1;
		int bestRank = Integer.MAX_VALUE;
		for (int slot = 0; slot < offerKeys.size(); slot++)
		{
			String key = offerKeys.get(slot);
			Integer rank = key == null ? null : ranks.get(key);
			if (rank == null)
			{
				return Recommendation.unavailable();
			}
			if (rank < bestRank)
			{
				bestSlot = slot;
				bestRank = rank;
			}
		}
		if (bestRank < acceptedCount)
		{
			return new Recommendation(Recommendation.Action.TAKE, bestSlot);
		}
		if (points < 0)
		{
			return Recommendation.unavailable();
		}
		return new Recommendation(points >= SKIP_COST ? Recommendation.Action.SKIP : Recommendation.Action.TAKE,
			bestSlot);
	}

	private static String stringValue(JsonElement value)
	{
		return value != null && value.isJsonPrimitive() && value.getAsJsonPrimitive().isString()
			? value.getAsString() : null;
	}

	private static int integerValue(JsonElement value, String field)
	{
		if (value != null && value.isJsonPrimitive() && value.getAsJsonPrimitive().isNumber())
		{
			try
			{
				return new BigDecimal(value.getAsString()).intValueExact();
			}
			catch (NumberFormatException | ArithmeticException e)
			{
				throw new IllegalArgumentException(field + " must be a whole number.");
			}
		}
		throw new IllegalArgumentException(field + " must be a whole number.");
	}
}

package com.efficientmortimer;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;

final class EfficientMortimerOverlay extends Overlay
{
	private static final Color HIGHLIGHT = Color.CYAN;
	private static final Color FILL = new Color(0, 255, 255, 22);
	private static final Color NOTICE_BACKGROUND = new Color(48, 200, 215, 150);
	private static final Font FONT = FontManager.getRunescapeFont();
	private static final int NOTICE_WIDTH = 240;
	private static final int PADDING = ComponentConstants.STANDARD_BORDER;
	private static final int GAP = 8;
	private static final BasicStroke OUTLINE = new BasicStroke(2);
	private final Client client;
	private final EfficientMortimerPlugin plugin;
	private final MortimerOffers offers;
	private final PanelComponent noticePanel = new PanelComponent();

	@Inject
	EfficientMortimerOverlay(Client client, EfficientMortimerPlugin plugin, MortimerOffers offers)
	{
		this.client = client;
		this.plugin = plugin;
		this.offers = offers;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		EfficientMortimerPlugin.DisplayState state = plugin.getDisplayState();
		if (state == null)
		{
			return null;
		}

		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			Recommendation recommendation = state.recommendation;
			if (recommendation != null && recommendation.getAction() == Recommendation.Action.TAKE)
			{
				Rectangle bounds = offers.getBounds(state.snapshot, recommendation.getSlot());
				if (bounds != null)
				{
					g.setColor(FILL);
					g.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
					g.setColor(HIGHLIGHT);
					g.setStroke(OUTLINE);
					g.drawRect(bounds.x + 1, bounds.y + 1, bounds.width - 2, bounds.height - 2);
				}
			}
			else
			{
				boolean skip = recommendation != null && recommendation.getAction() == Recommendation.Action.SKIP;
				String message = skip ? null : state.message;
				Rectangle content = offers.getContentBounds(state.snapshot);
				if (content != null && (skip || message != null))
				{
					Widget frame = client.getWidget(InterfaceID.SlayerTaskChoice.FRAME);
					Rectangle anchor = frame != null && !frame.isHidden() ? frame.getBounds() : content;
					noticePanel.setBackgroundColor(skip ? NOTICE_BACKGROUND : ComponentConstants.STANDARD_BACKGROUND_COLOR);
					drawNotice(g, anchor, skip ? "Skip these offers" : "No recommendation", message);
				}
			}
		}
		finally
		{
			g.dispose();
		}
		return null;
	}

	private void drawNotice(Graphics2D graphics, Rectangle anchor, String title, String message)
	{
		graphics.setFont(FONT);
		FontMetrics metrics = graphics.getFontMetrics();
		int maxWidth = Math.min(NOTICE_WIDTH, client.getCanvasWidth() - GAP * 2);
		List<String> lines = wrap(title, metrics, maxWidth - PADDING * 2);
		if (message != null)
		{
			lines.addAll(wrap(message, metrics, maxWidth - PADDING * 2));
		}
		int textWidth = 0;
		for (String line : lines)
		{
			textWidth = Math.max(textWidth, metrics.stringWidth(line));
		}
		int width = textWidth + PADDING * 2;
		int height = PADDING * 2 + metrics.getHeight() * lines.size();
		int x = Math.max(GAP, Math.min(anchor.x + (anchor.width - width) / 2, client.getCanvasWidth() - width - GAP));
		int y = anchor.y + anchor.height + GAP;
		if (y + height > client.getCanvasHeight() - GAP)
		{
			y = anchor.y - height - GAP;
			if (y < GAP)
			{
				x = anchor.x + anchor.width + GAP;
				if (x + width > client.getCanvasWidth() - GAP)
				{
					x = anchor.x - width - GAP;
				}
				if (x < GAP)
				{
					return;
				}
				y = Math.max(GAP, Math.min(anchor.y, client.getCanvasHeight() - height - GAP));
			}
		}
		noticePanel.setPreferredLocation(new Point(x, y));
		noticePanel.setPreferredSize(new Dimension(width, 0));
		noticePanel.getChildren().clear();
		for (String line : lines)
		{
			noticePanel.getChildren().add(LineComponent.builder().left(line).build());
		}
		noticePanel.render(graphics);
	}

	private static List<String> wrap(String text, FontMetrics metrics, int width)
	{
		List<String> lines = new ArrayList<>();
		String line = "";
		for (String word : text.split(" "))
		{
			String next = line.isEmpty() ? word : line + " " + word;
			if (!line.isEmpty() && metrics.stringWidth(next) > width)
			{
				lines.add(line);
				line = word;
			}
			else
			{
				line = next;
			}
		}
		lines.add(line);
		return lines;
	}
}

package com.efficientmortimer;

final class Recommendation
{
	enum Action
	{
		TAKE,
		SKIP,
		UNAVAILABLE
	}

	private final Action action;
	private final int slot;

	Recommendation(Action action, int slot)
	{
		this.action = action;
		this.slot = slot;
	}

	static Recommendation unavailable()
	{
		return new Recommendation(Action.UNAVAILABLE, -1);
	}

	Action getAction()
	{
		return action;
	}

	int getSlot()
	{
		return slot;
	}
}

package com.efficientmortimer;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.util.Text;

final class MortimerOffers
{
	private static final int MORTIMER_MASTER_ID = 10;
	// The task-choice script creates ten children per offer and three for a locked row.
	private static final int CARD_CHILD_COUNT = 10;
	private static final int[] OFFER_VARBITS = {
		VarbitID.SLAYER_CHOOSE_TASK_1,
		VarbitID.SLAYER_CHOOSE_TASK_1_MODIFIER_ID,
		VarbitID.SLAYER_CHOOSE_TASK_1_MODIFIER_VALUE,
		VarbitID.SLAYER_CHOOSE_TASK_1_MODIFIER_NEGATIVE,
		VarbitID.SLAYER_CHOOSE_TASK_2,
		VarbitID.SLAYER_CHOOSE_TASK_2_MODIFIER_ID,
		VarbitID.SLAYER_CHOOSE_TASK_2_MODIFIER_VALUE,
		VarbitID.SLAYER_CHOOSE_TASK_2_MODIFIER_NEGATIVE,
		VarbitID.SLAYER_CHOOSE_TASK_3,
		VarbitID.SLAYER_CHOOSE_TASK_3_MODIFIER_ID,
		VarbitID.SLAYER_CHOOSE_TASK_3_MODIFIER_VALUE,
		VarbitID.SLAYER_CHOOSE_TASK_3_MODIFIER_NEGATIVE
	};

	private final Client client;

	@Inject
	MortimerOffers(Client client)
	{
		this.client = client;
	}

	Snapshot read()
	{
		Widget content = content();
		if (content == null)
		{
			return null;
		}

		int[] state = readState();
		Widget[] children = content.getDynamicChildren();
		if (children == null || state[0] == 0 || state[4] == 0)
		{
			return Snapshot.incomplete(content, state, "Waiting for Mortimer's offers.");
		}

		int count = state[8] == 0 ? 2 : 3;
		int expectedChildren = count * CARD_CHILD_COUNT + (count == 2 ? 3 : 0);
		if (children.length != expectedChildren || (count == 2 && !lockedThirdChoice(children)))
		{
			return Snapshot.incomplete(content, state, "Unable to read Mortimer's offers.");
		}

		List<String> keys = new ArrayList<>(count);
		Widget[] cards = new Widget[count];
		String[] titles = new String[count];
		String[] modifiers = new String[count];
		for (int slot = 0; slot < count; slot++)
		{
			int child = slot * CARD_CHILD_COUNT;
			int variable = slot * 4;
			if (!visibleType(children[child], WidgetType.RECTANGLE)
				|| !visibleType(children[child + 1], WidgetType.TEXT)
				|| !visibleType(children[child + 2], WidgetType.TEXT)
				|| !visibleType(children[child + 6], WidgetType.TEXT)
				|| !plainText(children[child + 2]).startsWith("Amount: "))
			{
				return Snapshot.incomplete(content, state, "Unable to read Mortimer's offers.");
			}

			String taskName = taskName(state[variable]);
			String taskId = TaskCatalog.taskIdForName(taskName);
			String modifier = modifierId(state[variable + 1]);
			if (taskId == null || modifier == null || !TaskCatalog.isValidKey(taskId + "/" + modifier))
			{
				return Snapshot.incomplete(content, state, "Unrecognized Mortimer offer. Update Efficient Mortimer.");
			}

			String title = plainText(children[child + 1]);
			String modifierText = plainText(children[child + 6]);
			if (!taskName.equalsIgnoreCase(title)
				|| !modifierText(state[variable + 1], state[variable + 2], state[variable + 3]).equals(modifierText))
			{
				return Snapshot.incomplete(content, state, "Waiting for Mortimer's offers.");
			}

			keys.add(taskId + "/" + modifier);
			cards[slot] = children[child];
			titles[slot] = title;
			modifiers[slot] = modifierText;
		}
		return new Snapshot(content, state, keys, cards, titles, modifiers, null);
	}

	boolean isCurrent(Snapshot snapshot)
	{
		if (snapshot == null || content() != snapshot.content || !matchesState(snapshot.state))
		{
			return false;
		}
		for (int slot = 0; slot < snapshot.cards.length; slot++)
		{
			int child = slot * CARD_CHILD_COUNT;
			if (snapshot.content.getChild(child) != snapshot.cards[slot]
				|| snapshot.cards[slot].isHidden()
				|| !visibleType(snapshot.content.getChild(child + 1), WidgetType.TEXT)
				|| !visibleType(snapshot.content.getChild(child + 6), WidgetType.TEXT)
				|| !snapshot.titles[slot].equals(plainText(snapshot.content.getChild(child + 1)))
				|| !snapshot.modifiers[slot].equals(plainText(snapshot.content.getChild(child + 6))))
			{
				return false;
			}
		}
		return true;
	}

	Rectangle getBounds(Snapshot snapshot, int slot)
	{
		if (!isCurrent(snapshot) || slot < 0 || slot >= snapshot.cards.length)
		{
			return null;
		}
		return new Rectangle(snapshot.cards[slot].getBounds());
	}

	Rectangle getContentBounds(Snapshot snapshot)
	{
		return isCurrent(snapshot) ? new Rectangle(snapshot.content.getBounds()) : null;
	}

	private Widget content()
	{
		Widget content = client.getWidget(InterfaceID.SlayerTaskChoice.CONTENT);
		return content == null || content.isHidden()
			|| client.getVarbitValue(VarbitID.SLAYER_CHOOSE_ROLLED_MASTER) != MORTIMER_MASTER_ID
			? null : content;
	}

	private int[] readState()
	{
		int[] state = new int[OFFER_VARBITS.length];
		for (int i = 0; i < OFFER_VARBITS.length; i++)
		{
			state[i] = client.getVarbitValue(OFFER_VARBITS[i]);
		}
		return state;
	}

	private boolean matchesState(int[] state)
	{
		for (int i = 0; i < OFFER_VARBITS.length; i++)
		{
			if (client.getVarbitValue(OFFER_VARBITS[i]) != state[i])
			{
				return false;
			}
		}
		return true;
	}

	private String taskName(int taskId)
	{
		List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
		if (rows == null || rows.size() != 1)
		{
			return null;
		}
		Object[] names = client.getDBTableField(rows.get(0), DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0);
		return names != null && names.length == 1 && names[0] instanceof String ? (String) names[0] : null;
	}

	private static boolean lockedThirdChoice(Widget[] children)
	{
		String message = plainText(children[21]);
		return visibleType(children[20], WidgetType.RECTANGLE)
			&& visibleType(children[21], WidgetType.TEXT)
			&& (message.equals("Complete 50 tasks with Mortimer to unlock a third choice.")
				|| message.equals("You and your Slayer partner must complete 50 tasks with Mortimer to unlock a third choice."));
	}

	private static boolean visibleType(Widget widget, int type)
	{
		return widget != null && !widget.isHidden() && widget.getType() == type;
	}

	private static String plainText(Widget widget)
	{
		return widget == null || widget.getText() == null ? ""
			: Text.removeTags(widget.getText()).replace('\u00a0', ' ').trim();
	}

	private static String modifierId(int id)
	{
		switch (id)
		{
			case 1: return "points";
			case 2: return "quantity";
			case 3: return "clue";
			case 4: return "unique";
			case 5: return "xp";
			default: return null;
		}
	}

	private static String modifierText(int id, int value, int negative)
	{
		String amount = (id == 2 && negative == 1 ? "-" : "+") + value;
		switch (id)
		{
			case 1: return amount + " Slayer points";
			case 2: return amount + " Assigned";
			case 3: return amount + "% Clue chance";
			case 4: return amount + "% Superior unique chance";
			case 5: return amount + "% Slayer XP";
			default: return "";
		}
	}

	static final class Snapshot
	{
		private final Widget content;
		private final int[] state;
		private final List<String> keys;
		private final Widget[] cards;
		private final String[] titles;
		private final String[] modifiers;
		private final String message;

		private Snapshot(Widget content, int[] state, List<String> keys, Widget[] cards,
			String[] titles, String[] modifiers, String message)
		{
			this.content = content;
			this.state = state;
			this.keys = Collections.unmodifiableList(keys);
			this.cards = cards;
			this.titles = titles;
			this.modifiers = modifiers;
			this.message = message;
		}

		private static Snapshot incomplete(Widget content, int[] state, String message)
		{
			return new Snapshot(content, state, Collections.emptyList(), new Widget[0],
				new String[0], new String[0], message);
		}

		boolean isComplete()
		{
			return message == null;
		}

		List<String> getKeys()
		{
			return keys;
		}

		String getMessage()
		{
			return message;
		}
	}
}

